import crypto from 'node:crypto';
import net from 'node:net';
import tls from 'node:tls';
import type { Duplex } from 'node:stream';
import { Client, type ClientChannel, type SFTPWrapper } from 'ssh2';

/**
 * Where a VM world's SSH server answers, and how to trust it. The host key is
 * generated by karmax and installed into the VM at create (`vm/boot.ts`), so
 * the connection is pinned to it: no trust on first use, no known_hosts.
 */
export interface SshEndpoint {
  host: string;
  port: number;
  /** Reach sshd through a TLS-terminating proxy (Fly's `tls` handler on a
   * shared IPv4): TLS to `host:port` with this SNI name, then plain SSH. */
  tls?: { servername: string };
  /** `ssh-ed25519 AAAA…`, the only host key accepted. */
  hostKey: string;
  username: string;
  privateKey: string;
}

/** A dropped connection, so callers (and isTransportError) can tell it from
 * a command's own failure. */
export class VmTransportError extends Error {
  readonly code = 'ECONNRESET';
  constructor(message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = 'VmTransportError';
  }
}

export interface SshKeyPair { privateKey: string; publicKey: string }

/**
 * A fresh ed25519 key pair in OpenSSH formats, from node:crypto. (ssh2's own
 * generator writes about one key in 400 that ssh2 itself then rejects as
 * malformed: a world with such a key could never be reached.)
 */
export function generateSshKeyPair(comment = 'karmax'): SshKeyPair {
  const jwk = crypto.generateKeyPairSync('ed25519').privateKey.export({ format: 'jwk' });
  const seed = Buffer.from(jwk.d!, 'base64url');
  const pub = Buffer.from(jwk.x!, 'base64url');
  const string = (value: Buffer | string) => {
    const bytes = Buffer.from(value);
    const length = Buffer.alloc(4);
    length.writeUInt32BE(bytes.length);
    return Buffer.concat([length, bytes]);
  };
  const blob = Buffer.concat([string('ssh-ed25519'), string(pub)]);
  const check = crypto.randomBytes(4);
  let secret = Buffer.concat([check, check, string('ssh-ed25519'), string(pub), string(Buffer.concat([seed, pub])), string(comment)]);
  // Pad to the cipher block size ("none": 8) with 1, 2, 3, …
  const pad = (8 - (secret.length % 8)) % 8;
  secret = Buffer.concat([secret, Buffer.from(Array.from({ length: pad }, (_, index) => index + 1))]);
  const nkeys = Buffer.alloc(4);
  nkeys.writeUInt32BE(1);
  const body = Buffer.concat([Buffer.from('openssh-key-v1\0'), string('none'), string('none'), string(''), nkeys, string(blob), string(secret)]);
  const lines = body.toString('base64').match(/.{1,70}/g)!.join('\n');
  return { privateKey: `-----BEGIN OPENSSH PRIVATE KEY-----\n${lines}\n-----END OPENSSH PRIVATE KEY-----\n`,
    publicKey: `ssh-ed25519 ${blob.toString('base64')} ${comment}` };
}

export interface SshChannel {
  /** Write to the command's stdin; resolves once handed to the connection. */
  write(data: string | Buffer): Promise<void>;
  end(): void;
  /** Settles when the channel closes: the command's status, or the transport error that ended it. */
  done: Promise<{ code: number | null; signal?: string }>;
  close(): void;
}

export interface ExecBytesResult { stdout: Buffer; stderr: Buffer; code: number }

const CONNECT_TIMEOUT_MS = 30_000;

/**
 * One multiplexed SSH connection to a VM, reopened on demand. Every command,
 * file transfer and port forward is a channel on it; a connection that drops
 * fails the channels open on it (VmTransportError) and the next call dials
 * again, through `endpoint()` so a VM that moved (a woken Hetzner server has a
 * new address) is found where it is now.
 */
export class SshTransport {
  private client?: Promise<Client>;
  private live?: Client;
  private sftpSession?: Promise<SFTPWrapper>;
  private closed = false;

  constructor(private endpoint: () => Promise<SshEndpoint>, private options: {
    /** Test seam and proxy hook: open the byte stream SSH runs over. */
    socket?: (endpoint: SshEndpoint) => Promise<Duplex>;
    connectTimeoutMs?: number;
    keepaliveMs?: number;
  } = {}) {}

  /** Dial (or reuse) the connection. */
  async connection(): Promise<Client> {
    if (this.closed) throw new VmTransportError('VM connection closed');
    if (!this.client) {
      const pending = this.dial();
      this.client = pending;
      pending.catch(() => { if (this.client === pending) this.client = undefined; });
    }
    return this.client;
  }

  private async dial(): Promise<Client> {
    const endpoint = await this.endpoint();
    const sock = await (this.options.socket ?? defaultSocket)(endpoint);
    const expected = Buffer.from(endpoint.hostKey.trim().split(/\s+/)[1] ?? '', 'base64');
    if (!expected.length) throw new Error('VM host key is missing');
    const client = new Client();
    client.setMaxListeners(0); // one `close` listener per open channel, hundreds at once
    return new Promise<Client>((resolve, reject) => {
      let ready = false;
      const forget = () => {
        if (this.live !== client) return;
        this.live = undefined;
        this.client = undefined;
        this.sftpSession = undefined;
      };
      client.on('ready', () => { ready = true; this.live = client; resolve(client); });
      client.on('error', (error) => {
        if (!ready) reject(new VmTransportError(`could not reach the VM over SSH: ${error.message}`, { cause: error }));
        forget();
      });
      client.on('close', () => {
        if (!ready) reject(new VmTransportError('the VM closed the SSH connection before it was ready'));
        forget();
      });
      client.connect({
        sock, username: endpoint.username, privateKey: endpoint.privateKey,
        hostVerifier: (key: Buffer) => key.equals(expected),
        readyTimeout: this.options.connectTimeoutMs ?? CONNECT_TIMEOUT_MS,
        keepaliveInterval: this.options.keepaliveMs ?? 15_000, keepaliveCountMax: 4,
      });
    });
  }

  /** Start `command` and stream its output. */
  async open(command: string, handlers: { stdout?: (chunk: Buffer) => void; stderr?: (chunk: Buffer) => void } = {}): Promise<SshChannel> {
    const client = await this.connection();
    let exit: { code: number | null; signal?: string } | undefined;
    const stream = await new Promise<ClientChannel>((resolve, reject) => {
      try {
        client.exec(command, (error, channel) => {
          if (error) {
            reject(isChannelRefusal(error) ? error : new VmTransportError(`SSH exec failed: ${error.message}`, { cause: error }));
            return;
          }
          // Now, not after the await: ssh2 parses a whole received chunk at once,
          // and a short command's output, exit status and close often arrive in
          // the exec reply's chunk (behind Fly's TLS edge, under load, mostly).
          // Output waits in the stream; an `exit` event with no listener is lost.
          channel.on('exit', (code: number | null, signal?: string) => {
            exit = { code: typeof code === 'number' ? code : null, ...(signal ? { signal } : {}) };
          });
          resolve(channel);
        });
      } catch (error) {
        reject(new VmTransportError(`SSH exec failed: ${(error as Error).message}`, { cause: error }));
      }
    });
    const done = new Promise<{ code: number | null; signal?: string }>((resolve, reject) => {
      stream.on('data', (chunk: Buffer) => handlers.stdout?.(chunk));
      stream.stderr.on('data', (chunk: Buffer) => handlers.stderr?.(chunk));
      const lost = () => reject(new VmTransportError('the SSH connection to the VM was lost'));
      client.once('close', lost);
      stream.on('close', () => {
        client.removeListener('close', lost);
        // A channel can close because its connection did; only an exit status proves the command ended.
        if (exit) resolve(exit); else lost();
      });
    });
    done.catch(() => undefined);
    return {
      write: (data) => new Promise<void>((resolve, reject) => {
        if (stream.destroyed || !stream.writable) { reject(new VmTransportError('the SSH channel is closed')); return; }
        stream.write(data, (error) => error ? reject(new VmTransportError(error.message, { cause: error })) : resolve());
      }),
      end: () => { stream.end(); },
      done,
      close: () => { stream.close(); },
    };
  }

  /** Run a command to completion. A command still running at `timeoutMs` is
   * killed with its process group (coreutils `timeout`) and reported as a
   * timeout, not an exit status. */
  async exec(command: string, options: { input?: string | Buffer; timeoutMs?: number; signal?: AbortSignal } = {}): Promise<ExecBytesResult> {
    options.signal?.throwIfAborted();
    const seconds = options.timeoutMs ? Math.max(1, Math.ceil(options.timeoutMs / 1000)) : undefined;
    const line = seconds ? `exec timeout -k 5 ${seconds} sh -c ${quote(command)}` : command;
    const stdout: Buffer[] = [], stderr: Buffer[] = [];
    const started = Date.now();
    const channel = await this.open(line, { stdout: (chunk) => stdout.push(chunk), stderr: (chunk) => stderr.push(chunk) });
    if (options.input !== undefined) await channel.write(options.input).catch(() => undefined);
    channel.end();
    let timer: NodeJS.Timeout | undefined;
    const abort = () => channel.close();
    options.signal?.addEventListener('abort', abort, { once: true });
    try {
      const backstop = seconds ? new Promise<never>((_, reject) => {
        timer = setTimeout(() => { channel.close(); reject(timeoutError(options.timeoutMs!)); }, (seconds + 15) * 1000);
      }) : undefined;
      const exit = await (backstop ? Promise.race([channel.done, backstop]) : channel.done);
      options.signal?.throwIfAborted();
      if (seconds && (exit.code === 124 || exit.code === 137) && Date.now() - started >= seconds * 1000)
        throw timeoutError(options.timeoutMs!);
      return { stdout: Buffer.concat(stdout), stderr: Buffer.concat(stderr),
        code: exit.code ?? (exit.signal ? 128 + (SIGNALS[exit.signal] ?? 0) : -1) };
    } finally {
      if (timer) clearTimeout(timer);
      options.signal?.removeEventListener('abort', abort);
    }
  }

  async sftp(): Promise<SFTPWrapper> {
    const client = await this.connection();
    if (!this.sftpSession) {
      const pending = new Promise<SFTPWrapper>((resolve, reject) => client.sftp((error, sftp) => {
        if (error) { reject(new VmTransportError(`SFTP failed: ${error.message}`, { cause: error })); return; }
        sftp.on('close', () => { if (this.sftpSession === pending) this.sftpSession = undefined; });
        resolve(sftp);
      }));
      this.sftpSession = pending;
      pending.catch(() => { if (this.sftpSession === pending) this.sftpSession = undefined; });
    }
    return this.sftpSession;
  }

  async readFile(remotePath: string): Promise<Buffer> {
    const chunks: Buffer[] = [];
    for await (const chunk of this.readStream(remotePath)) chunks.push(chunk);
    return Buffer.concat(chunks);
  }

  /** A file's bytes, streamed; stops reading when the consumer stops. */
  async *readStream(remotePath: string, range: { start?: number; end?: number } = {}): AsyncGenerator<Buffer> {
    const sftp = await this.sftp();
    const stream = sftp.createReadStream(remotePath, { ...range, highWaterMark: 256 * 1024 });
    try {
      for await (const chunk of stream) yield chunk as Buffer;
    } catch (error) {
      throw sftpError(error, remotePath);
    } finally {
      // Closing the remote handle can still fail after the last byte (the
      // connection closed first, say by a park): nothing is lost then, and an
      // error nobody listens to would be an uncaught exception in the worker.
      stream.on('error', () => undefined);
      stream.destroy();
    }
  }

  async writeFile(remotePath: string, content: Buffer, mode = 0o644): Promise<void> {
    const sftp = await this.sftp();
    await new Promise<void>((resolve, reject) => {
      const stream = sftp.createWriteStream(remotePath, { mode });
      stream.on('error', (error: unknown) => reject(sftpError(error, remotePath)));
      stream.on('close', () => resolve());
      stream.end(content);
    });
  }

  /** A byte stream to `127.0.0.1:port` inside the VM (an SSH direct-tcpip
   * channel), so nothing in the VM listens publicly for previews. */
  async forward(port: number): Promise<Duplex> {
    const client = await this.connection();
    return new Promise<Duplex>((resolve, reject) => client.forwardOut('127.0.0.1', 0, '127.0.0.1', port, (error, stream) =>
      error ? reject(Object.assign(new Error(`nothing is listening on port ${port} in the VM: ${error.message}`), { code: 'ECONNREFUSED' }))
        : resolve(stream)));
  }

  /** Drop the connection; the next call dials again. */
  reset(): void {
    const current = this.client;
    this.client = undefined;
    this.live = undefined;
    this.sftpSession = undefined;
    void current?.then((client) => client.end(), () => undefined);
  }

  close(): void {
    this.closed = true;
    this.reset();
  }
}

async function defaultSocket(endpoint: SshEndpoint): Promise<Duplex> {
  return new Promise<Duplex>((resolve, reject) => {
    const fail = (error: Error) => reject(new VmTransportError(`could not reach the VM at ${endpoint.host}:${endpoint.port}: ${error.message}`, { cause: error }));
    if (endpoint.tls) {
      const socket = tls.connect({ host: endpoint.host, port: endpoint.port, servername: endpoint.tls.servername });
      socket.setTimeout(CONNECT_TIMEOUT_MS, () => socket.destroy(new Error('TLS handshake timed out')));
      socket.once('secureConnect', () => { socket.setTimeout(0); resolve(socket); });
      socket.once('error', fail);
    } else {
      const socket = net.connect({ host: endpoint.host, port: endpoint.port });
      socket.setTimeout(CONNECT_TIMEOUT_MS, () => socket.destroy(new Error('connection timed out')));
      socket.once('connect', () => { socket.setTimeout(0); resolve(socket); });
      socket.once('error', fail);
    }
  });
}

/** sshd refusing a channel (MaxSessions) is the server saying no, not a lost connection. */
function isChannelRefusal(error: Error): boolean {
  return /open failed|administratively prohibited/i.test(error.message);
}

function sftpError(error: unknown, remotePath: string): Error {
  const code = (error as { code?: number })?.code;
  // SFTP status 2 is "no such file": never a missing VM (isMissingSandbox).
  if (code === 2) return Object.assign(new Error(`no such file in the VM: ${remotePath}`), { name: 'FileNotFoundError', code: 'ENOENT' });
  if (code === 3) return Object.assign(new Error(`permission denied in the VM: ${remotePath}`), { code: 'EACCES' });
  return error instanceof Error ? error : new Error(String(error));
}

function timeoutError(ms: number): Error {
  return Object.assign(new Error(`command timed out after ${Math.round(ms / 1000)} s`), { name: 'TimeoutError' });
}

const SIGNALS: Record<string, number> = { HUP: 1, INT: 2, QUIT: 3, KILL: 9, SEGV: 11, PIPE: 13, TERM: 15 };

export function quote(value: string): string { return `'${value.replace(/'/g, `'\\''`)}'`; }
